 INSERT INTO QaChecklistTemplateItems (Category, FeatureName, ItemText, SortOrder)
 VALUES
 (N'Browser UI', N'Sidebar', N'Click a pane button (e.g. Bookmarks) in the collapsed sidebar strip - **Expected:** sidebar auto-expands and loads that pane''s content.', 1),
 (N'Browser UI', N'Sidebar', N'Click the expand/collapse button in the pane strip - **Expected:** sidebar animates open/closed smoothly.', 2),
 (N'Browser UI', N'Sidebar', N'Right-click the sidebar -> "Undock Sidebar" - **Expected:** sidebar detaches into a floating frameless widget snapped to a screen edge; docked sidebar in the browser window disappears.', 3),
 (N'Browser UI', N'Sidebar', N'Drag the undocked floating widget to a different screen edge - **Expected:** it snaps to the nearest edge (left/right/top/bottom) within ~80px.', 4),
 (N'Browser UI', N'Sidebar', N'Leave the undocked widget idle (don''t touch it) for ~5 seconds - **Expected:** it auto-hides to a thin 4px peek strip; moving the cursor onto the strip reveals it again.', 5),
 (N'Browser UI', N'Sidebar', N'Right-click the undocked widget -> "Dock Sidebar" - **Expected:** it re-attaches inside the browser window at its last docked position.', 6),
 (N'Browser UI', N'Sidebar', N'Drag the sidebar''s inner resize handle (docked, expanded) - **Expected:** sidebar width changes and persists after restart.', 7),
 (N'Browser UI', N'Sidebar', N'Open Settings -> pin a site by URL under "Web Panels" - **Expected:** a new globe-icon button appears in the pane strip; clicking it loads the live site in place, keeping scroll/session state when you switch away and back.', 8),
 (N'Browser UI', N'Sidebar', N'On any New Tab Page layout, click the gear/settings icon - **Expected:** sidebar opens directly to the NTP Settings panel.', 9),
 (N'Browser UI', N'Sidebar Apps', N'Right-click a desktop `.lnk` shortcut (e.g. Notepad) - **Expected:** "Add to Wanderlust Sidebar" appears in the context menu.', 10),
 (N'Browser UI', N'Sidebar Apps', N'Click it while the browser is already running - **Expected:** an icon for the app appears at the bottom of the sidebar''s button strip within a couple seconds, no new window opens.', 11),
 (N'Browser UI', N'Sidebar Apps', N'Click the pinned app icon in the sidebar - **Expected:** the target application launches as a normal Windows process.', 12),
 (N'Browser UI', N'Sidebar Apps', N'Right-click the pinned app icon in the sidebar -> "Remove from Sidebar" - **Expected:** the icon disappears from the strip.', 13),
 (N'Browser UI', N'Sidebar Apps', N'Add the same shortcut twice (or two different shortcuts pointing at the same .exe) - **Expected:** only one icon appears (silent de-dupe by executable path).', 14),
 (N'Browser UI', N'Sidebar Apps', N'Repeat the "Add to Wanderlust Sidebar" step with the browser fully closed - **Expected:** browser launches, opens a normal window, and the app is pinned (same end state as the running-browser case).', 15),
 (N'Browser UI', N'Panels (extension floating windows)', N'Load the `panels-test` extension unpacked via `chrome://extensions` (enable Developer mode first) - **Expected:** loads without errors.', 16),
 (N'Browser UI', N'Panels (extension floating windows)', N'Click the extension''s toolbar icon and use its popup to create a panel - **Expected:** a small frameless window appears docked to the bottom-right of the screen, showing real page content (not a black rectangle).', 17),
 (N'Browser UI', N'Panels (extension floating windows)', N'Open several panels in a row - **Expected:** they pack right-to-left along the bottom edge and auto-shrink to fit.', 18),
 (N'Browser UI', N'Panels (extension floating windows)', N'Drag one panel on top of another - **Expected:** they merge into a vertical stack.', 19),
 (N'Browser UI', N'Panels (extension floating windows)', N'Close a panel via its own close (X) button - **Expected:** panel disappears cleanly, no crash.', 20),
 (N'Browser UI', N'Panels (extension floating windows)', N'Check `chrome://extensions` -> Details -> "Inspect views" or the task manager (`Shift+Esc`) while a panel is open - **Expected:** the panel''s WebContents shows up as its own row.', 21),
 (N'Browser UI', N'Panels (extension floating windows)', N'As of v1.8.20: open one docked panel, one detached panel (drag it away from the edge), and stack two more panels together, then fully restart the browser - **Expected:** the docked panel comes back docked, the two stacked panels come back stacked together in the same order, and the detached one comes back detached - not everything collapsed to detached (the old behavior; before this fix, panels didn''t reopen at all after a restart).', 22),
 (N'Browser UI', N'Panels (extension floating windows)', N'Close one panel out of a 3-panel stack (via its own close button), leaving 2 - **Expected:** the remaining 2-panel stack still restores correctly after a restart (not the closed one, which shouldn''t reappear).', 23),
 (N'Browser UI', N'Panels (extension floating windows)', N'As of v1.8.22: from the extension''s background page/console, call `chrome.windows.create({type:''detached_panel'', url:''...''})` - **Expected:** a free-floating detached panel opens (not docked to the screen edge, and not an error) - previously this call errored with "invalid window type."', 24),
 (N'Browser UI', N'Custom HTML Infobars', N'Load the `infobars-test` extension unpacked via `chrome://extensions` - **Expected:** loads without errors.', 25),
 (N'Browser UI', N'Custom HTML Infobars', N'Open any `http(s)` page (not a `chrome://` page), click the extension''s toolbar icon, then click a basic test button - **Expected:** a horizontal HTML banner appears above the page content, below the tab strip.', 26),
 (N'Browser UI', N'Custom HTML Infobars', N'Click the banner''s close (X) button - **Expected:** banner dismisses; the popup''s log records the dismissal exactly once.', 27),
 (N'Browser UI', N'Custom HTML Infobars', N'Trigger a test button that grows/shrinks its own content height dynamically - **Expected:** the infobar smoothly animates to the new height (clamped to a max of 72px) without a page reload.', 28),
 (N'Browser UI', N'Custom HTML Infobars', N'Navigate the tab to a different URL while the infobar is showing - **Expected:** infobar is dismissed automatically.', 29),
 (N'Browser UI', N'Custom HTML Infobars', N'Try triggering an infobar on a `chrome://` page (e.g. `chrome://settings`) - **Expected:** the call fails with an "Unable to attach infobar to tab" style error, since system pages have no infobar manager.', 30),
 (N'Browser UI', N'Browser Tools (app menu utilities)', N'Open several tabs, then app menu -> Restart - **Expected:** browser closes and reopens with all previous tabs restored.', 31),
 (N'Browser UI', N'Browser Tools (app menu utilities)', N'Visit a page, force-reload it once (`Ctrl+Shift+R`) so it''s cached, then app menu -> Restart & Clear Cache - **Expected:** browser restarts; force-reloading the same page afterward shows a fresh 200 response, not a 304 from cache.', 32),
 (N'Browser UI', N'Browser Tools (app menu utilities)', N'Open `chrome://memory-internals`, note renderer memory usage, then app menu -> Flush Memory - **Expected:** no tabs close; reloading `chrome://memory-internals` shows measurably lower renderer memory footprint (most visible with many tabs/heavy JS open).', 33),
 (N'Browser UI', N'Browser Tools (app menu utilities)', N'Toggle app menu -> "Reuse This Window for Popups" on - **Expected:** menu item shows a checkmark.', 34),
 (N'Browser UI', N'Browser Tools (app menu utilities)', N'With it toggled on, visit a page that does `window.open()` or has a `target="_blank"` link - **Expected:** it opens as a new foreground tab in the same window instead of a new window.', 35),
 (N'Browser UI', N'Browser Tools (app menu utilities)', N'Toggle it off and repeat - **Expected:** normal new-window behavior returns. Open a second browser window and confirm its toggle state is independent (per-window, not global, and resets to off after a restart).', 36),
 (N'Browser UI', N'Splash Screen', N'Fully close the browser, then relaunch it - **Expected:** a small (480x280) dark-navy window with "WanderLust" and "Private - Fast - Yours" text appears on top, without stealing focus from the main browser window.', 37),
 (N'Browser UI', N'Splash Screen', N'Wait without interacting - **Expected:** after 2.5 seconds the splash window fades and closes on its own (~300ms fade).', 38),
 (N'Browser UI', N'Splash Screen', N'While the splash screen is visible, check Alt+Tab / the taskbar - **Expected:** the splash window does not appear in either (Windows `WS_EX_TOOLWINDOW`).', 39),
 (N'Browser UI', N'Splash Screen', N'Try clicking into the main browser window while splash is showing - **Expected:** main window is interactive immediately; splash screen doesn''t block input.', 40),
 (N'Browser UI', N'Tab Utilities (context menu commands)', N'Right-click a tab -> Copy URL - **Expected:** clipboard contains that tab''s current URL.', 41),
 (N'Browser UI', N'Tab Utilities (context menu commands)', N'Open several tabs, right-click any tab -> Copy All URLs - **Expected:** clipboard contains a newline-separated list of every open tab''s URL.', 42),
 (N'Browser UI', N'Tab Utilities (context menu commands)', N'Right-click a tab -> Clone Tab to New Window - **Expected:** a new regular browser window opens with the same URL, no shared cookies/history/session with the original.', 43),
 (N'Browser UI', N'Tab Utilities (context menu commands)', N'Right-click a tab in a normal (non-incognito) window -> Clone Tab to Incognito - **Expected:** an incognito window opens with the same URL.', 44),
 (N'Browser UI', N'Tab Utilities (context menu commands)', N'Right-click a tab that is already incognito - **Expected:** "Clone Tab to Incognito" is not shown in the menu.', 45),
 (N'Browser UI', N'Tab Utilities (context menu commands)', N'Open 4-5 tabs, right-click one in the middle -> Close Tabs to Left - **Expected:** all unpinned tabs to its left close; tabs to the right and the tab itself remain.', 46),
 (N'Browser UI', N'Tab Behaviors (scroll, double-click, keep-last-tab)', N'Hover the mouse over the tab strip (not a specific tab) and scroll the wheel down - **Expected:** the next tab to the right becomes active; scrolling at the last tab wraps to the first.', 47),
 (N'Browser UI', N'Tab Behaviors (scroll, double-click, keep-last-tab)', N'Scroll up - **Expected:** the previous tab becomes active, wrapping at the first tab.', 48),
 (N'Browser UI', N'Tab Behaviors (scroll, double-click, keep-last-tab)', N'Double-click the body of a tab (not its close button) - **Expected:** that tab closes immediately.', 49),
 (N'Browser UI', N'Tab Behaviors (scroll, double-click, keep-last-tab)', N'With only one tab open in a window, close it via the tab''s close button or `Ctrl+W` - **Expected:** (default behavior) a new blank tab opens first, then the old tab closes - the window stays open rather than closing.', 50),
 (N'Browser UI', N'Tab Shapes', N'Navigate to `chrome://settings/customTab` - **Expected:** a "Tab Shape" section appears with three preview options (Round/Rectangle/Trapezoid).', 51),
 (N'Browser UI', N'Tab Shapes', N'Click "Rectangle" - **Expected:** open browser tabs visually update to sharp rectangular corners immediately, no restart needed.', 52),
 (N'Browser UI', N'Tab Shapes', N'Click "Trapezoid" - **Expected:** tabs update to the angled trapezoid shape.', 53),
 (N'Browser UI', N'Tab Shapes', N'Click "Round" to return to default - **Expected:** tabs return to rounded corners.', 54),
 (N'Browser UI', N'Tab Shapes', N'Toggle the browser to dark mode with a non-default shape selected - **Expected:** the settings-page preview swaps to its dark-mode image variant.', 55),
 (N'Browser UI', N'Tab Shapes', N'Restart the browser after picking a non-default shape - **Expected:** the chosen shape persists (falls back to Round only if the pref is somehow corrupted).', 56),
 (N'Browser UI', N'Vertical Tabs', N'Enable the vertical tabs pref in Settings - **Expected:** horizontal tab strip disappears; a narrow (~50px) vertical column of tab icons appears on the configured side.', 57),
 (N'Browser UI', N'Vertical Tabs', N'Hover the mouse over the collapsed bar - **Expected:** it animates outward to ~250px, revealing full tab titles and close (X) buttons; moving the mouse away shrinks it back.', 58),
 (N'Browser UI', N'Vertical Tabs', N'Click the pin button (visible once the bar is expanded) - **Expected:** the bar locks open at a fixed width and stops responding to hover; a resize handle appears on its inner edge.', 59),
 (N'Browser UI', N'Vertical Tabs', N'Drag the resize handle while pinned - **Expected:** bar width changes live and persists after restart.', 60),
 (N'Browser UI', N'Vertical Tabs', N'Open a new tab (`Ctrl+T`) and navigate somewhere - **Expected:** a new button appears in the vertical strip live, with favicon and title updating as the page loads.', 61),
 (N'Browser UI', N'Vertical Tabs', N'Open tabs to a few sites with distinctly-colored favicons (e.g. a red-logo site, a blue-logo site) and expand the bar - **Expected:** each tab button shows a thin color stripe on its bar-position edge roughly matching that site''s favicon color, once the favicon finishes loading.', 62),
 (N'Browser UI', N'Vertical Tabs', N'Open a tab to a site with no favicon (or before one loads) - **Expected:** stripe falls back to the hostname-heuristic category color (e.g. YouTube/Netflix -> red, GitHub/Stack Overflow -> green) instead of showing nothing or a stale color from a previous tab.', 63),
 (N'Browser UI', N'Vertical Tabs', N'Right-click a tab with a visible favicon-color stripe -> assign it to a manual tab group with a group color - **Expected:** the stripe switches to the group''s chosen color, overriding the favicon-derived color.', 64),
 (N'Browser UI', N'Vertical Tabs', N'Open a link with ctrl-click / middle-click from an existing tab, then right-click empty space in the bar -> note a parent/child relationship - **Expected:** with Tree mode enabled (settings), the new tab appears indented as a child with a disclosure triangle on the parent.', 65),
 (N'Browser UI', N'Vertical Tabs', N'Right-click empty space below the tab buttons -> "Sort tabs by" -> Title - **Expected:** unpinned, ungrouped tabs reorder alphabetically; pinned/grouped tabs stay put.', 66),
 (N'Browser UI', N'Vertical Tabs', N'Right-click empty space -> "Save tabs as new session", then close those tabs, then right-click -> "Restore session >" and pick it - **Expected:** all previously-open tabs reopen as background tabs.', 67),
 (N'Browser UI', N'Vertical Tabs', N'As of v1.8.29: save a session, restart the browser, and confirm it still appears under "Restore session >" and restores correctly - **Expected:** the new `schemaVersion` field on each saved session (added for future forward-compat) doesn''t change or break normal save/restore behavior.', 68),
 (N'Browser UI', N'Vertical Tabs', N'Ctrl-click (Cmd-click on Mac) two different tab buttons - **Expected:** both are added to a multi-selection (visually highlighted); right-click -> Close should close both.', 69),
 (N'Browser UI', N'Vertical Tabs', N'Press "/" while a tab button has focus - **Expected:** a search/filter row appears; typing narrows the visible tabs to title/URL matches; Escape clears it.', 70),
 (N'Browser UI', N'Vertical Tabs', N'Hover a tab button for about half a second without clicking - **Expected:** a small floating thumbnail preview of that tab''s page appears beside it.', 71),
 (N'Browser UI', N'Vertical Tabs', N'With focus on a tab button, press `j`/`k` (or arrow keys) - **Expected:** as of v1.8.25, focus moves down/up between tab buttons *and* the newly-focused tab becomes active (its page shows in the content area) - not just a focus-ring move. `Home`/`End` jump to first/last with the same activation.', 72),
 (N'Browser UI', N'Vertical Tabs', N'With vim visual-select mode active (`v` while a tab has focus), press `j`/`k` to extend the selection across several tabs - **Expected:** no crash or double-activation glitching; each step extends the highlighted multi-selection normally (the new activate-on-arrow code path is explicitly skipped while in visual mode, so it doesn''t add any new activation calls on top of whatever selection-extension already does).', 73),
 (N'Browser UI', N'Vertical Tabs', N'**Vertical -> horizontal switch-back** (status genuinely unclear as of 2026-08-17 - see `docs/chromium/debugging/vertical-to-horizontal-switch.md`): Launch fresh in horizontal mode. In Settings, change "Tab bar position" away from Top (e.g. Left) - vertical bar should appear and work correctly. Then change it back to Top. **Expected (if actually fixed):** the horizontal tab strip repaints immediately with all tabs and the upstream `+` new-tab button visible, no restart needed. **Known-broken symptoms to watch for (if NOT fixed):** tab strip area blank except a small chevron at the top-left, no `+` button, and/or tabs briefly flicker blank when opening a new tab via Ctrl+T before self-correcting. Repeat the horizontal->vertical->horizontal cycle 2-3 times - the original bug reproduced on every cycle, not just the first. Report the actual result either way (even "still broken" or "confirmed fixed") back to the doc - six previous fix attempts were each believed to have failed, and a seventh (undocumented) fix land', 74),
 (N'Browser UI', N'Container Tabs', N'Go to `chrome://settings/containers` and create two containers with different names/colors - **Expected:** both appear in a list, editable/deletable.', 75),
 (N'Browser UI', N'Container Tabs', N'Right-click empty vertical-tab-bar space -> "New tab in container >" -> pick container A, log into a site (e.g. an email provider) - **Expected:** new tab opens normally, no special container UI chrome, but is isolated.', 76),
 (N'Browser UI', N'Container Tabs', N'Repeat with container B, same site - **Expected:** you can log in as a different account without being logged out of the first.', 77),
 (N'Browser UI', N'Container Tabs', N'Ctrl-click a link inside a container tab - **Expected:** the newly opened child tab inherits the same container (same logged-in session, no fresh login).', 78),
 (N'Browser UI', N'Container Tabs', N'Trigger a `window.open()` popup from a container tab (e.g. an OAuth "login with provider" popup) - **Expected:** popup also lands in the same container.', 79),
 (N'Browser UI', N'Container Tabs', N'Restart the browser with a container tab open (or use "reopen closed tab") - **Expected:** as of v1.8.17, the restored tab keeps its container''s isolated storage (still logged in as the container''s account) rather than falling back to the default partition.', 80),
 (N'Browser UI', N'Container Tabs', N'Save a tab group containing a container tab, close it, then reopen the saved group - **Expected:** the reopened tab keeps its container''s isolated storage. Note: this mapping is local to this device (not synced), so reopening the same saved group on a different device will not carry the container assignment there.', 81),
 (N'Browser UI', N'Container Tabs', N'Open a container tab, force-discard it (`chrome://discards` or via the memory saver settings), then reactivate it by switching to its tab - **Expected:** container isolation survives the discard/reactivate cycle.', 82),
 (N'Browser UI', N'Custom Download Shelf', N'Download any file - **Expected:** a shelf bar slides up from the bottom of the window immediately (no ~2s delay like upstream Chrome), showing the file''s progress, icon, and name.', 83),
 (N'Browser UI', N'Custom Download Shelf', N'Right-click a download item in the shelf - **Expected:** context menu includes Open, Pause/Resume/Cancel (while active), plus "Hide", "Delete from list", and "Delete file".', 84),
 (N'Browser UI', N'Custom Download Shelf', N'Click "Hide" on an item - **Expected:** item disappears from the shelf for this session (download history still has it).', 85),
 (N'Browser UI', N'Custom Download Shelf', N'Click "Delete file" on a completed download - **Expected:** the file is removed from disk and from the download list/history.', 86),
 (N'Browser UI', N'Custom Download Shelf', N'Go to `chrome://settings/customOthers` and enable "Use Chrome''s download bubble instead of the custom download shelf" - **Expected:** next download shows Chrome''s normal small bubble near the toolbar instead of the bottom shelf.', 87),
 (N'Browser UI', N'Custom Download Shelf', N'Toggle "Invisible download bar" on (same settings section) - **Expected:** downloads are still tracked/listed at `chrome://downloads` but no shelf bar visually appears.', 88),
 (N'Browser UI', N'Custom Download Shelf', N'Toggle the download toolbar button visibility pref - **Expected:** the download icon in the toolbar shows/hides accordingly.', 89),
 (N'Browser UI', N'Enhanced Omnibox', N'Type `settings:` followed by a partial section name (e.g. `settings: passwords`, `settings: privacy`) - **Expected:** a suggestion appears with the matching section''s label, navigating directly to the right `chrome://settings/<section>` sub-page on selection (not the settings hub page).', 90),
 (N'Browser UI', N'Enhanced Omnibox', N'Type `settings: appearance` - **Expected:** a suggestion appears (note: both `appearance` and `appearance-and-layout` routes share the "Appearance" label, so either may surface as the top match).', 91),
 (N'Browser UI', N'Enhanced Omnibox', N'Subscribe to an RSS feed via `chrome://reader`, then type a few characters from one of its item titles into the omnibox - **Expected:** a suggestion labeled "RSS" appears; selecting it navigates to that item''s link.', 92),
 (N'Browser UI', N'Enhanced Omnibox', N'With no RSS feeds subscribed (or omnibox search disabled under `chrome://settings/rss`), type text that would otherwise match an RSS item - **Expected:** no RSS suggestion appears, no crash.', 93),
 (N'Browser UI', N'Enhanced Omnibox', N'Type a plain search query into the omnibox - **Expected:** normal suggestions appear (bookmarks/history/search engine) with no crash or visual corruption.', 94),
 (N'Browser UI', N'Enhanced Omnibox', N'Type a full URL into the omnibox - **Expected:** the URL displays normally with the usual security indicator (lock icon / "Not secure", etc.) - unchanged, since URL Formatting/Security Indicators were not part of this pass.', 95),
 (N'Browser UI', N'Split View', N'Press `Ctrl+Shift+E` - **Expected:** a secondary panel opens taking up half the content width, with a draggable divider between it and the main page.', 96),
 (N'Browser UI', N'Split View', N'Right-click a link on any page -> "Open link in split view" - **Expected:** the link''s target loads directly into the split panel (main tab is undisturbed).', 97),
 (N'Browser UI', N'Split View', N'Drag the divider left/right - **Expected:** panel/main-content split ratio changes live; dragging to an extreme stops at a minimum ~100px for either side (can''t fully collapse either pane).', 98),
 (N'Browser UI', N'Split View', N'Click a link inside the split panel - **Expected:** navigation happens inside the panel itself; it never opens a new tab.', 99),
 (N'Browser UI', N'Split View', N'Click into the split panel to focus it, then look at the omnibox - **Expected:** omnibox URL updates to reflect the panel''s page.', 100),
 (N'Browser UI', N'Split View', N'With the panel focused, type a new URL in the omnibox and press Enter - **Expected:** the panel navigates (not the main tab).', 101),
 (N'Browser UI', N'Split View', N'Press `Ctrl+Shift+E` again (or click the toolbar button) - **Expected:** panel and divider close, main content reclaims the full width.', 102),
 (N'Browser UI', N'Workspaces (Spaces)', N'Right-click empty vertical-tab-bar space -> "New workspace" - **Expected:** a new workspace is created and immediately becomes active (auto-named "Workspace N" since there''s no text-prompt dialog).', 103),
 (N'Browser UI', N'Workspaces (Spaces)', N'Go to `chrome://settings/workspaces` - **Expected:** the new workspace appears in a list; you can edit its name, color, assigned sidebar panel, assigned saved tab groups, and assigned proxy routing rules.', 104),
 (N'Browser UI', N'Workspaces (Spaces)', N'Save a tab group (right-click a tab group header -> save), then assign that saved group to a workspace in the settings page - **Expected:** the group shows as checked/assigned in the workspace''s edit form.', 105),
 (N'Browser UI', N'Workspaces (Spaces)', N'Create a second workspace and assign a different saved tab group to it - **Expected:** each workspace independently lists only its own assigned groups.', 106),
 (N'Browser UI', N'Workspaces (Spaces)', N'Right-click the vertical tab bar -> "Switch workspace >" -> pick the second workspace - **Expected:** the first workspace''s assigned tab group collapses (or hides) in the tab strip, and the second workspace''s tab group opens/expands; this happens in every open browser window of the same profile, not just the active one.', 107),
 (N'Browser UI', N'Workspaces (Spaces)', N'Assign different sidebar panels (e.g. Bookmarks vs. RSS) to two workspaces, then switch between them - **Expected:** the sidebar''s active panel switches to match each workspace automatically.', 108),
 (N'Browser UI', N'Workspaces (Spaces)', N'Delete the currently active workspace via Settings - **Expected:** it''s removed from the list and there is no longer an active workspace (no crash, no orphaned checkmark in the switch menu).', 109),
 (N'Browser UI', N'Boss Key', N'Go to `chrome://settings/customOthers` and enable the boss key checkbox - **Expected:** a "configure shortcut" row becomes visible (previously hidden) showing the current shortcut text (default `Ctrl+F9`).', 110),
 (N'Browser UI', N'Boss Key', N'Click into the shortcut field and press a new key combination (e.g. `Ctrl+Shift+B`) - **Expected:** the field enters a "capturing" state (visibly highlighted), then displays the new combination once a valid key is pressed, and saves it as the new shortcut.', 111),
 (N'Browser UI', N'Boss Key', N'Press Escape while the field is capturing, before pressing a real combination - **Expected:** capture cancels and the field reverts to its previous value.', 112),
 (N'Browser UI', N'Boss Key', N'With the boss key enabled and a shortcut set, click elsewhere to unfocus Settings, then press the configured shortcut anywhere (even outside the browser window, since this is a global accelerator) - **Expected:** browser hides/minimizes instantly.', 113),
 (N'Browser UI', N'Boss Key', N'Press the shortcut again - **Expected:** browser returns/restores.', 114),
 (N'Browser UI', N'Boss Key', N'Uncheck the boss key checkbox - **Expected:** the shortcut row hides again and the global shortcut stops responding.', 115),
 (N'Browser UI', N'Boss Key', N'With two browser windows/profiles open and boss key enabled in both with the same shortcut - **Expected:** no crash; only one instance''s registration is actually active at a time (per the service''s own conflict-avoidance), and disabling one profile''s boss key hands the registration off to the other if it''s still enabled.', 116),
 (N'Input & Interaction', N'Mouse Gestures', N'Hold the right mouse button on a normal webpage and drag in a shape, then release - **Expected:** a stroke trail/direction-label overlay draws live during the drag (Windows only; other platforms execute the action with no visual trail), and on release the resolved action (per the mapping currently shown/configured in the Mouse Gesture settings page) executes; no context menu appears.', 117),
 (N'Input & Interaction', N'Mouse Gestures', N'Right-click and release quickly without dragging (no recognized stroke) - **Expected:** the normal right-click context menu appears (the buffered mouse-down/up is replayed to the renderer).', 118),
 (N'Input & Interaction', N'Mouse Gestures', N'Open the Mouse Gesture settings page and use the gesture capture canvas to record a new stroke -> action mapping, then perform that exact stroke on a page - **Expected:** the newly configured action fires and matches the label shown during the drag.', 119),
 (N'Input & Interaction', N'Mouse Gestures', N'Hold the right mouse button and scroll the wheel up - **Expected:** on Windows, default action is "select previous tab" (`SELECT_PREVIOUS_TAB`); on Mac default is no-op (`NO_ACTIONS`) unless configured. No context menu appears on release.', 120),
 (N'Input & Interaction', N'Mouse Gestures', N'Hold the right mouse button and scroll the wheel down - **Expected:** on Windows, default action is "select next tab" (`SELECT_NEXT_TAB`); Mac default no-op.', 121),
 (N'Input & Interaction', N'Mouse Gestures', N'Hold the right mouse button down, then click (press) the left mouse button while right is still held - **Expected:** triggers the "Flip Back" locker action (default `NO_ACTIONS` - configure a real action in settings first to observe an effect, then repeat this test).', 122),
 (N'Input & Interaction', N'Mouse Gestures', N'Hold the left mouse button down, then click the right mouse button while left is still held - **Expected:** triggers the "Flip Forward" locker action (default `NO_ACTIONS` - configure then retest).', 123),
 (N'Input & Interaction', N'Mouse Gestures', N'With the master toggle (`mouse_gesture.enabled`) turned off in settings - **Expected:** right-drag no longer produces gesture behavior; normal right-click context menu works as stock Chromium.', 124),
 (N'Input & Interaction', N'Autoscroll (Middle-Click Scroll)', N'On a long scrollable page, click the middle mouse button on empty page content - **Expected:** the scroll-anchor cursor icon appears and moving the mouse pans the page (stock behavior).', 125),
 (N'Input & Interaction', N'Autoscroll (Middle-Click Scroll)', N'Go to Settings -> Others -> Web content and check "Disable autoscroll" - **Expected:** setting saves immediately.', 126),
 (N'Input & Interaction', N'Autoscroll (Middle-Click Scroll)', N'Without reloading the tab, click the middle mouse button on the same page again - **Expected:** autoscroll no longer activates (per doc, the pref propagates live via `pref_watcher.cc`, no reload required).', 127),
 (N'Input & Interaction', N'Autoscroll (Middle-Click Scroll)', N'Uncheck "Disable autoscroll" in settings, then middle-click the page again - **Expected:** autoscroll cursor mode resumes.', 128),
 (N'Input & Interaction', N'Autoscroll (Middle-Click Scroll)', N'With autoscroll disabled, middle-click directly on a link - **Expected:** link still opens in a new background tab (unrelated stock Chromium behavior, not gated by this pref).', 129),
 (N'Input & Interaction', N'Super Drag', N'Select some text on a page, drag it **upward** more than ~25px, release - **Expected:** default action `BACKGROUND_TAB` fires - the dragged text/link opens as a search or URL in a new background tab; a drag-tip bubble shows the resolved action during the drag.', 130),
 (N'Input & Interaction', N'Super Drag', N'Repeat the same drag **downward** - **Expected:** also opens in a new background tab (default for all 4 cardinal directions).', 131),
 (N'Input & Interaction', N'Super Drag', N'Repeat dragging a link **left**, then **right** - **Expected:** both open the link in a new background tab by default.', 132),
 (N'Input & Interaction', N'Super Drag', N'Drag a link or text diagonally (e.g., up-and-left) - **Expected:** default mapping for diagonal/combined directions is `NO_ACTIONS`; no super-drag action fires (drop falls through to normal renderer drag-drop).', 133),
 (N'Input & Interaction', N'Super Drag', N'Drag content only a few pixels (well under the 25px reaction distance) and release - **Expected:** super drag never activates; normal browser drag/drop behavior occurs instead.', 134),
 (N'Input & Interaction', N'Super Drag', N'In the Super Drag settings page, add the current site to `super_drag.exceptions`, then repeat a cardinal drag on that site - **Expected:** super drag is fully suppressed on that page.', 135),
 (N'Input & Interaction', N'Super Drag', N'Drag an image downward - **Expected:** default `BACKGROUND_TAB` opens the image URL in a new background tab (verify vs. explicit `OPEN_IMAGE_IN_NEW_TAB` mapping if reconfigured).', 136),
 (N'Input & Interaction', N'Super Drag', N'Toggle off `super_drag.tip_enabled` in settings, repeat a drag - **Expected:** no visual bubble/overlay appears during the drag, but the action still fires on drop.', 137),
 (N'Input & Interaction', N'Super Drag', N'As of v1.8.19: in the Super Drag settings page, assign a search engine to one gesture direction (e.g. up), then drag a hyperlink (not plain text) in that direction and release - **Expected:** the drop searches the search engine using the link''s visible text as the query, opening a search-results page - not a direct navigation to the link''s href. The mid-drag bubble should also show the "search with X" hint while dragging, not just the disposition label.', 138),
 (N'Input & Interaction', N'Super Drag', N'Repeat the same drag in a direction with **no** search engine assigned - **Expected:** unchanged existing behavior - the link opens directly (navigates to its href).', 139),
 (N'Input & Interaction', N'Super Drag', N'As of v1.8.29: assign a search engine to a gesture, then click "Reset to default" in the Super Drag settings page - **Expected:** the assignment is actually cleared this time (a pre-existing bug meant Reset silently did nothing to search-engine assignments before this fix), and gesture direction mappings return to their defaults.', 140),
 (N'Input & Interaction', N'Enhanced Scroll Animation System', N'Scroll a long page with the mouse wheel using default settings - **Expected:** scroll animates smoothly with an ease-in-out feel, completing quickly (10-30ms depending on scroll delta) rather than jumping instantly.', 141),
 (N'Input & Interaction', N'Enhanced Scroll Animation System', N'Relaunch the browser with `--custom-scroll-duration=100` and scroll the same page - **Expected:** each wheel-scroll animation visibly takes longer/slower than default.', 142),
 (N'Input & Interaction', N'Enhanced Scroll Animation System', N'Relaunch with `--custom-scroll-velocity=200` and perform small wheel flicks - **Expected:** the max-duration ramp is reached at a much smaller scroll distance than default (animation "maxes out" sooner).', 143),
 (N'Input & Interaction', N'Enhanced Scroll Animation System', N'Relaunch with `--disable-enhanced-scrolling` and scroll - **Expected:** scrolling falls back to stock Chromium scroll-animation behavior (graceful fallback, no crash).', 144),
 (N'Input & Interaction', N'Enhanced Scroll Animation System', N'Perform rapid successive wheel scrolls in quick succession - **Expected:** no stutter, dropped frames, or animation queue buildup.', 145),
 (N'Input & Interaction', N'Enhanced Scroll Animation System', N'Compare wheel-scroll feel against trackpad/touch scroll on the same page - **Expected:** enhanced animation applies to wheel scrolling; touch/trackpad scrolling remains unaffected (per doc''s intended integration scope).', 146),
 (N'Input & Interaction', N'Typed Input History', N'Click the address bar, type a full URL directly (e.g. `github.com`) and press Enter to navigate (must be typed, not pasted/clicked) - **Expected:** navigation commits normally.', 147),
 (N'Input & Interaction', N'Typed Input History', N'Later, click the address bar and type a matching prefix (e.g. `gith`) - **Expected:** the previously typed URL appears as a ranked suggestion in the dropdown.', 148),
 (N'Input & Interaction', N'Typed Input History', N'Type and navigate to the same URL several more times, then retype the prefix - **Expected:** that suggestion ranks higher/first as its frecency score (frequency + recency) increases.', 149),
 (N'Input & Interaction', N'Typed Input History', N'Open an Incognito window and type a prefix that matches a URL typed in the regular profile - **Expected:** the suggestion still appears (read-only sharing from the parent profile), but navigating with it does not add/alter entries in the regular profile''s history (Incognito typed navigations aren''t recorded).', 150),
 (N'Input & Interaction', N'Typed Input History', N'Fully close and relaunch the browser, then retype a previously-used prefix - **Expected:** the suggestion is still present (data persisted to `typed_input_history.json`, reloaded lazily on first use).', 151),
 (N'Input & Interaction', N'Typed Input History', N'Navigate to a URL by clicking a link or bookmark (not typing) - **Expected:** this does NOT get recorded as typed history (only `PAGE_TRANSITION_TYPED` navigations qualify).', 152),
 (N'Privacy & Security', N'Ad Blocker', N'Visit a typical news site or ad-heavy page (loads `doubleclick.net`, `google-analytics.com`, etc.) - **Expected:** omnibox shows an "ads off" badge icon shortly after load.', 153),
 (N'Privacy & Security', N'Ad Blocker', N'Click the badge icon - **Expected:** a bubble opens listing the blocked hosts for the current page.', 154),
 (N'Privacy & Security', N'Ad Blocker', N'Open DevTools -> Network tab, reload the page - **Expected:** blocked requests show status `(blocked:other)` with tooltip referencing `wanderlust-adblock`.', 155),
 (N'Privacy & Security', N'Ad Blocker', N'Toggle "Block ads and trackers" off in Settings, reload the page - **Expected:** badge disappears, blocked count is zero.', 156),
 (N'Privacy & Security', N'Ad Blocker', N'Navigate to a fresh tab - **Expected:** badge is hidden and any open bubble reflects an empty state.', 157),
 (N'Privacy & Security', N'Ad Blocker', N'Visit a page with cosmetic (element-hiding) rules (e.g. a site with a known ad-container div) - **Expected:** the hidden element does not render (inspect via View Source vs rendered DOM - the element exists in DOM but has injected `display:none` style).', 158),
 (N'Privacy & Security', N'Ad Blocker', N'As of v1.8.18: visit a page matching a `/regex/`-style EasyList rule (or add one locally to `bundled_filter_rules.cc` for testing) - **Expected:** the matching request is now blocked, where before it silently passed through.', 159),
 (N'Privacy & Security', N'Ad Blocker', N'As of v1.8.26: force a background refresh (temporarily shrink `custom.filter_list_refresh.interval_hours`, or delete `WanderLustAdBlockCache.txt` and restart) - **Expected:** a fetch to `easylist.to` occurs, `WanderLustAdBlockCache.txt` appears under the user-data dir, and `BlockersWorker` picks up the new rules without a restart (verify by blocking a host only present in the freshly fetched list, not the bundled snapshot).', 160),
 (N'Privacy & Security', N'Ad Blocker', N'As of v1.8.26: restart the browser after a successful refresh - **Expected:** the ad blocker loads from `WanderLustAdBlockCache.txt` on startup rather than the bundled `bundled_filter_rules.cc` snapshot (check via `VLOG(1)` output or a deliberately stale bundled marker rule).', 161),
 (N'Privacy & Security', N'Ad Blocker', N'As of v1.8.26: feed the updater a truncated/near-empty response (e.g. a local test server, or briefly lower the sanity threshold) - **Expected:** the fetch is rejected, a `LOG(WARNING)` fires, and the existing engine/cache is left untouched.', 162),
 (N'Privacy & Security', N'Tracking Parameter Removal (Privacy Guard / URL Purify)', N'Enable the toggle, then navigate to `https://example.com/page?utm_source=newsletter&utm_medium=email&id=123` - **Expected:** DevTools -> Network -> the request URL shows only `?id=123`.', 163),
 (N'Privacy & Security', N'Tracking Parameter Removal (Privacy Guard / URL Purify)', N'Click through from a Google search result - **Expected:** outbound request lacks `ved`, `ei`, `usg`, etc.', 164),
 (N'Privacy & Security', N'Tracking Parameter Removal (Privacy Guard / URL Purify)', N'As of v1.8.26: after a background refresh has run (see "Filter list auto-refresh" below), visit a URL matching a ClearURLs-only provider not in the original hardcoded per-site list - **Expected:** its tracking parameters are stripped, confirming the fetched rules are live.', 165),
 (N'Privacy & Security', N'Tracking Parameter Removal (Privacy Guard / URL Purify)', N'Disable the toggle and reload the same tracked URL - **Expected:** all original query params are preserved in the outbound request.', 166),
 (N'Privacy & Security', N'Tracking Parameter Removal (Privacy Guard / URL Purify)', N'Open a new tab (custom NTP) with the toggle enabled - **Expected:** NTP''s own backend API calls are unaffected (check DevTools on the `chrome-search://` frame).', 167),
 (N'Privacy & Security', N'Filter list auto-refresh (Ad Blocker + URL Purify)', N'Open Settings -> Privacy and security - **Expected:** "Filter list updates" section shows the "Automatically update filter lists" toggle, on by default.', 168),
 (N'Privacy & Security', N'Filter list auto-refresh (Ad Blocker + URL Purify)', N'Toggle it off, restart the browser - **Expected:** neither the EasyList/EasyPrivacy fetch nor the ClearURLs fetch fires on startup (no new request to `easylist.to` / the ClearURLs data source; no cache file timestamp update).', 169),
 (N'Privacy & Security', N'Filter list auto-refresh (Ad Blocker + URL Purify)', N'Toggle it back on, restart - **Expected:** both fetches resume on their normal schedule (immediately if overdue, per `last_fetch_time + interval`).', 170),
 (N'Privacy & Security', N'Filter list auto-refresh (Ad Blocker + URL Purify)', N'Quit and relaunch the browser shortly after a successful fetch (well inside the 96-hour interval) - **Expected:** no new fetch fires - `custom.filter_list_refresh.last_adblock_fetch_time` / `.last_url_purify_fetch_time` correctly suppress a redundant re-fetch.', 171),
 (N'Privacy & Security', N'Privacy Shield (unified toolbar panel)', N'Click the shield icon - **Expected:** bubble opens showing six toggle rows and a 4-cell stats strip (Ads blocked / Params stripped / Referrers stripped / Trackers on page).', 172),
 (N'Privacy & Security', N'Privacy Shield (unified toolbar panel)', N'Toggle "Connection Control" on inside the bubble - **Expected:** the change is reflected immediately if `chrome://settings` is also open in another tab (no reload needed).', 173),
 (N'Privacy & Security', N'Privacy Shield (unified toolbar panel)', N'Visit a page that triggers ad blocks and tracker requests - **Expected:** the stats strip numbers update live while the bubble is open.', 174),
 (N'Privacy & Security', N'Privacy Shield (unified toolbar panel)', N'Click the footer link - **Expected:** navigates to `chrome://settings/privacy`.', 175),
 (N'Privacy & Security', N'Privacy Shield (unified toolbar panel)', N'Toggle "Show Privacy Shield button" off (if exposed) - **Expected:** the toolbar button disappears without restart.', 176),
 (N'Privacy & Security', N'Connection Control', N'Open Settings -> Security & Privacy -> Connection Control, add a deny rule (scope: private, protocol: any, port: 0), enable the feature - **Expected:** applies immediately, no restart required.', 177),
 (N'Privacy & Security', N'Connection Control', N'Navigate to `http://192.168.1.1` (or any private-IP address) - **Expected:** page fails with `ERR_BLOCKED_BY_CLIENT`.', 178),
 (N'Privacy & Security', N'Connection Control', N'Add an `allow` rule above the deny rule for that specific IP - **Expected:** the page now loads without a restart.', 179),
 (N'Privacy & Security', N'Connection Control', N'Set `enabled = false` - **Expected:** all traffic flows normally regardless of rules.', 180),
 (N'Privacy & Security', N'Connection Control', N'Visit any `chrome://` or `wanderlust://` page while a broad deny-all rule is active - **Expected:** internal pages are never blocked (always exempt).', 181),
 (N'Privacy & Security', N'Referrer Control', N'Enable "Strip Referrer" with an empty exceptions list, then click a link from one page to `https://developer.mozilla.org/` - **Expected:** DevTools -> Network -> Request Headers shows no `Referer` header on the navigation request.', 182),
 (N'Privacy & Security', N'Referrer Control', N'Add `developer.mozilla.org` to the exceptions list and repeat - **Expected:** `Referer` header reappears for that destination only.', 183),
